solution:
// Group (key, value) rows by key and summarize each group.
// A row's key is normalized first: leading and trailing whitespace is
// removed and ASCII letters are lowercased, so " Ab" and "aB" fall in the
// same group "ab" (inner spaces are kept). Rows whose normalized key is
// empty are ignored entirely.
// For each group, return the tuple (key, count, total, mean, spread): the
// normalized key, the number of rows, the sum of their values, the mean
// rounded down toward negative infinity (so the mean of -1 and -2 is -2),
// and the largest value minus the smallest.
// Only groups with at least min_count rows are returned, sorted by total
// descending, then by count descending, then by key ascending (plain
// character order).
// If min_count is less than 1, return None (even for empty rows).
// Examples:
//   group_aggregate([("a", 3), ("b", 10), ("A ", 4)], 1) == Some([("b", 1, 10, 10, 0), ("a", 2, 7, 3, 1)])
//   group_aggregate([("x", -1), ("x", -2), ("y", 5)], 2) == Some([("x", 2, -3, -2, 1)])
fn group_aggregate(rows: List[(Str, Int)], min_count: Int) -> Option[List[(Str, Int, Int, Int, Int)]] {
  if min_count < 1 {
    return None;
  }
  let mut groups: Map[Str, List[Int]] = map_new();
  for (key, value) in rows {
    let k = to_lower(trim(key));
    if k == "" {
      continue;
    }
    groups = map_set(groups, k, push(unwrap_or(map_get(groups, k), []), value));
  }
  let mut out: List[(Str, Int, Int, Int, Int)] = [];
  for k in map_keys(groups) {
    let vals = groups[k];
    let count = len(vals);
    if count >= min_count {
      let total = sum(vals);
      let spread = unwrap_or(max_of(vals), 0) - unwrap_or(min_of(vals), 0);
      out = push(out, (k, count, total, div_floor(total, count), spread));
    }
  }
  // stable sorts, least significant key first
  let by_key = sort_by_str(out, |g| g.0);
  let by_count = sort_by(by_key, |g| 0 - g.1);
  Some(sort_by(by_count, |g| 0 - g.2))
}
